```css
* { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --primary: #4a6fa5;
  --primary-dark: #3a5a8a;
  --bg: #f4f1ea;
  --card: #ffffff;
  --text: #2b2b2b;
  --muted: #777;
  --danger: #c0392b;
  --success: #27ae60;
  --warning: #e67e22;
  --border: #ddd6c8;
}

body {
  font-family: 'Segoe UI', Georgia, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
}

.hidden { display: none !important; }

/* ---------- Autenticação ---------- */
#auth-screen {
  display: flex; align-items: center; justify-content: center;
  min-height: 100vh; padding: 20px;
  background: linear-gradient(135deg, #4a6fa5 0%, #2c3e50 100%);
}
.auth-box {
  background: var(--card); border-radius: 12px; padding: 36px;
  width: 100%; max-width: 420px; box-shadow: 0 10px 40px rgba(0,0,0,.3);
}
.auth-box h1 { text-align: center; font-size: 1.7rem; margin-bottom: 6px; }
.subtitle { text-align: center; color: var(--muted); margin-bottom: 22px; font-size: .95rem; }

.tabs { display: flex; gap: 8px; margin-bottom: 20px; }
.tab {
  flex: 1; padding: 10px; border: 1px solid var(--border); background: #f8f6f1;
  border-radius: 8px; cursor: pointer; font-size: .95rem;
}
.tab.active { background: var(--primary); color: #fff; border-color: var(--primary); }

form label { display: block; margin: 12px 0 4px; font-size: .9rem; font-weight: 600; }
form input, form select, form textarea {
  width: 100%; padding: 10px 12px; border: 1px solid var(--border);
  border-radius: 8px; font-size: 1rem; background: #fffdf9;
}
form input:focus, form select:focus, form textarea:focus {
  outline: 2px solid var(--primary); border-color: var(--primary);
}

