    <h3 style="margin:22px 0 10px;">Histórico de devolvidos (${past.length})</h3>
    ${past.length ? `
      <div class="table-wrap"><table>
        <tr><th>Item</th><th>Retirado em</th><th>Devolvido em</th></tr>
